import json,random,sys,time,urllib.request,urllib.parse,os
R='C:/verger-data/pilot/registry/'
CITIES=['Paris','New York','London']
def ok(d):
    t=d['primaryType'] or ''
    return t in('restaurant','cafe','coffee_shop','pub','bar') or t.endswith('_restaurant') or t.endswith('_bar')
def sample():
    pools={c:[] for c in CITIES}
    for l in open('C:/verger-data/pilot/venues.ndjson',encoding='utf8'):
        if '"candidate": true' not in l: continue
        if '"Paris"' not in l and '"New York"' not in l and '"London"' not in l: continue
        d=json.loads(l)
        if d['candidate'] and d['city'] in pools and ok(d): pools[d['city']].append(d)
    for c,p in pools.items():
        p.sort(key=lambda d:d['venueId'])
        s=random.Random(20261021).sample(p,400)
        json.dump(s,open(R+'sample_%s.json'%c.replace(' ','_'),'w',encoding='utf8'),ensure_ascii=False)
        print(c,len(p),'pool',flush=True)
def get(url,hdr=None):
    for i in range(6):
        try:
            return json.load(urllib.request.urlopen(urllib.request.Request(url,headers=hdr or {}),timeout=30))
        except Exception as e:
            if i==5: return {'error':str(e)}
            time.sleep(1+2*i)
def fr():
    s=json.load(open(R+'sample_Paris.json',encoding='utf8'))
    B='https://recherche-entreprises.api.gouv.fr/'
    with open(R+'fr_raw.jsonl','w',encoding='utf8') as f:
        for d in s:
            q=urllib.parse.quote(d['name'][:80]);out={'venueId':d['venueId'],'res':[]}
            for e in 'AC':
                time.sleep(.17);out['res'].append(get(B+'search?q=%s&departement=75&section_activite_principale=I&etat_administratif=%s&per_page=25&limite_matching_etablissements=20'%(q,e)))
            for p in (1,2,3):
                time.sleep(.17);r=get(B+'near_point?lat=%s&long=%s&radius=0.1&section_activite_principale=I&per_page=25&page=%d&limite_matching_etablissements=20'%(d['lat'],d['lng'],p));out['res'].append(r)
                if len(r.get('results',[]))<25: break
            f.write(json.dumps(out,ensure_ascii=False)+'\n');f.flush()
def uk():
    s=json.load(open(R+'sample_London.json',encoding='utf8'))
    with open(R+'uk_raw.jsonl','w',encoding='utf8') as f:
        for d in s:
            time.sleep(.2)
            r=get('https://api.ratings.food.gov.uk/Establishments?name=%s&latitude=%s&longitude=%s&maxDistanceLimit=0.1&pageSize=50'%(urllib.parse.quote(d['name'][:80]),d['lat'],d['lng']),{'x-api-version':'2','accept':'application/json'})
            f.write(json.dumps({'venueId':d['venueId'],'res':r},ensure_ascii=False)+'\n');f.flush()
if __name__=='__main__':
    {'sample':sample,'fr':fr,'uk':uk}[sys.argv[1]]()
